def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    colors = {grid[r][c] for r, c in cells}
    inner = [color for color in colors if any(grid[r][c] == color for r in range(r0 + 1, r1) for c in range(c0 + 1, c1))]
    # The central color is the color that is not the enclosing rectangle color.
    counts = {color: sum(grid[r][c] == color for r, c in cells) for color in colors}
    outer = max(colors, key=lambda color: sum(grid[r][c] == color and (r in (r0, r1) or c in (c0, c1)) for r, c in cells))
    fill = next((color for color in colors if color != outer), outer)
    pts = [(r, c) for r, c in cells if grid[r][c] == fill]
    if not pts:
        return [row[:] for row in grid]
    margin = min(min(r-r0, r1-r, c-c0, c1-c) for r,c in pts)
    out = [row[:] for row in grid]
    for r in range(max(0, r0-margin), min(h, r1+margin+1)):
        for c in range(max(0, c0-margin), min(w, c1+margin+1)):
            if grid[r][c] == 0:
                out[r][c] = fill
    return out
